import { supabase } from '../data/supabase.js';
import { toast } from '../ui/feedback.js';
const modalRoot=document.querySelector('#modal-root');
let activeFilter='All';
let pollToken=0;

const esc=(v='')=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
const fmtDate=v=>{if(!v)return null;try{return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(v));}catch{return String(v)}};
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function cover(book,e){const src=e?.cover_url||'';return `<div class="edition-cover">${src?`<img src="${esc(src)}" alt="Cover of ${esc(book.title)}" loading="lazy" onerror="this.remove()">`:''}<div class="edition-cover-fallback"><strong>${esc(book.title)}</strong></div></div>`;}
function formatGroup(format=''){const f=String(format).toLowerCase();if(/hard/.test(f))return 'Hardcover';if(/paper|soft|mass market/.test(f))return 'Paperback';if(/kindle|ebook|e-book|electronic/.test(f))return 'eBook';if(/audio|cassette|cd/.test(f))return 'Audiobook';return 'Other';}
function isEnglish(e){const l=String(e.language||'').toLowerCase();return !l||l==='english'||l==='eng'||l==='en';}
function isPrint(e){return !['eBook','Audiobook'].includes(formatGroup(e.format||e.binding));}
function selectedId(book){return book.current_edition_id||book.reference_edition_id||book.display_edition_id||null;}
function isSelected(book,e){return e.id===selectedId(book);}
function completeness(e){return [e.cover_url,e.isbn13||e.isbn10,e.page_count,e.publisher,e.publication_year,e.format||e.binding].filter(Boolean).length;}
function sortEditions(book,rows){const sid=selectedId(book);return [...rows].sort((a,b)=>
 Number(b.id===sid)-Number(a.id===sid)||Number(Boolean(b.owned))-Number(Boolean(a.owned))||
 Number(isEnglish(b))-Number(isEnglish(a))||Number(isPrint(b))-Number(isPrint(a))||
 Number(Boolean(b.cover_url))-Number(Boolean(a.cover_url))||completeness(b)-completeness(a)||
 Number(b.publication_year||0)-Number(a.publication_year||0));}
function editionHeading(e){return [e.format||e.binding||'Edition',e.publication_year].filter(Boolean).join(' · ');}
function editionFacts(e){return [e.page_count?`${e.page_count} pages`:null,e.language,e.publication_date?`Published ${fmtDate(e.publication_date)}`:e.publication_year?`Published ${e.publication_year}`:null,e.publisher?`by ${e.publisher}`:null,e.isbn13||e.isbn10?`ISBN ${e.isbn13||e.isbn10}`:null].filter(Boolean);}
function badges(book,e){const out=[];if(isSelected(book,e))out.push(book.ownership_status==='Owned'?'Current edition':'Reference edition');if(e.owned)out.push('Owned copy');if(e.preferred_copy)out.push('Preferred');if(isEnglish(e)&&e.language)out.push('English');return out.map(x=>`<span>${esc(x)}</span>`).join('');}

async function fetchBundle(bookId){
 const [b,e,s]=await Promise.all([
  supabase.from('v_library').select('*').eq('id',bookId).single(),
  supabase.from('editions').select('*').eq('book_id',bookId),
  supabase.from('books').select('editions_status,editions_last_refreshed_at,editions_error').eq('id',bookId).single()
 ]);
 if(b.error)throw b.error;if(e.error)throw e.error;
 return {book:b.data,editions:sortEditions(b.data,e.data||[]),state:s.data||{}};
}
function actionButtons(bundle,e){const {book}=bundle;if(isSelected(book,e))return `<span class="edition-current-label">${book.ownership_status==='Owned'?'Current edition':'Current reference'}</span>`;const reading=['Currently Reading','Paused'].includes(book.overall_status);if(reading)return `<button class="btn btn-primary" type="button" data-edition-use="${e.id}">Switch reading edition</button>`;if(book.ownership_status==='Owned')return `<button class="btn btn-primary" type="button" data-edition-own="${e.id}">Use as my edition</button>`;return `<button class="btn btn-primary" type="button" data-edition-use="${e.id}">Use as reference</button><button class="btn edition-own-secondary" type="button" data-edition-own="${e.id}">Mark as owned copy</button>`;}
function editionCard(bundle,e){const {book}=bundle;return `<article class="edition-row ${isSelected(book,e)?'selected':''}" data-edition-row="${e.id}">${cover(book,e)}<div class="edition-row-copy"><div class="edition-badges">${badges(book,e)}</div><h3>${esc(editionHeading(e))}</h3>${e.edition_statement?`<p class="edition-statement">${esc(e.edition_statement)}</p>`:''}<div class="edition-facts">${editionFacts(e).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="edition-row-actions">${actionButtons(bundle,e)}</div></div></article>`;}
function filterRows(rows){if(activeFilter==='All')return rows;if(activeFilter==='English')return rows.filter(isEnglish);return rows.filter(e=>formatGroup(e.format||e.binding)===activeFilter);}
function filters(rows){const groups=['All'];if(rows.some(e=>isEnglish(e)))groups.push('English');for(const g of ['Paperback','Hardcover','eBook','Audiobook'])if(rows.some(e=>formatGroup(e.format||e.binding)===g))groups.push(g);return groups.length>1?`<div class="edition-filters">${groups.map(g=>`<button type="button" data-edition-filter="${esc(g)}" class="${activeFilter===g?'active':''}">${esc(g)}</button>`).join('')}</div>`:'';}
function summary(rows){const english=rows.filter(e=>isEnglish(e)).length,covers=rows.filter(e=>e.cover_url).length,print=rows.filter(isPrint).length;return `${rows.length} edition${rows.length===1?'':'s'} · ${english} English · ${covers} with covers · ${print} print`;}
function renderBrowser(bundle,{searching=false}={}){const {book,state}=bundle,rows=sortEditions(book,bundle.editions),filtered=filterRows(rows);modalRoot.innerHTML=`<div class="modal-backdrop edition-browser-backdrop"><section class="edition-browser-modal" role="dialog" aria-modal="true" aria-labelledby="edition-browser-title"><header class="edition-browser-head"><div><p class="eyebrow">Book editions</p><h2 id="edition-browser-title">${esc(book.title)}</h2><p>${book.ownership_status==='Owned'?'Choose the edition that matches your copy.':'English print editions with complete metadata and cover art are prioritised. You can switch the reference edition at any time.'}</p></div><button type="button" class="edition-close" data-edition-close aria-label="Close">×</button></header>${filters(rows)}<div class="edition-browser-status">${searching?`<span><span class="edition-spinner"></span> Finding editions… <small>${esc(summary(rows))}</small></span>`:`<span>${esc(summary(rows))}</span><button type="button" data-edition-refresh>${state.editions_last_refreshed_at?'Refresh editions':'Find editions'}</button>`}</div>${state.editions_error&&!searching?`<p class="edition-error">${esc(state.editions_error)}</p>`:''}<div class="edition-list">${filtered.length?filtered.map(e=>editionCard(bundle,e)).join(''):'<div class="edition-empty">No editions match this filter.</div>'}</div></section></div>`;bindBrowser(bundle);}
function close(){pollToken++;modalRoot.innerHTML='';activeFilter='All';}
function bindBrowser(bundle){modalRoot.querySelector('[data-edition-close]')?.addEventListener('click',close);modalRoot.querySelector('.edition-browser-backdrop')?.addEventListener('click',e=>{if(e.target.classList.contains('edition-browser-backdrop'))close();});modalRoot.querySelector('[data-edition-refresh]')?.addEventListener('click',()=>discover(bundle.book.id,true));modalRoot.querySelectorAll('[data-edition-filter]').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.editionFilter;renderBrowser(bundle,{searching:bundle.state?.editions_status==='refreshing'});}));modalRoot.querySelectorAll('[data-edition-use]').forEach(b=>b.addEventListener('click',()=>chooseEdition(bundle,b.dataset.editionUse,false)));modalRoot.querySelectorAll('[data-edition-own]').forEach(b=>b.addEventListener('click',()=>chooseEdition(bundle,b.dataset.editionOwn,true)));}

async function followBackground(bookId,{maxMs=120000}={}){const token=++pollToken,start=Date.now();let lastCount=-1;while(token===pollToken&&Date.now()-start<maxMs&&modalRoot.querySelector('.edition-browser-modal')){const bundle=await fetchBundle(bookId).catch(()=>null);if(bundle){const searching=bundle.state?.editions_status==='refreshing';if(bundle.editions.length!==lastCount||!searching){lastCount=bundle.editions.length;renderBrowser(bundle,{searching});}if(!searching)return bundle;}await sleep(2000);}return fetchBundle(bookId).catch(()=>null);}
async function discover(bookId,force=false){let before=null;try{before=await fetchBundle(bookId);renderBrowser(before,{searching:true});const invoke=supabase.functions.invoke('edition-options',{body:{book_id:bookId,force}}).catch(err=>({error:err}));const after=await followBackground(bookId,{maxMs:120000});const result=await invoke;const invokeError=result?.error||result?.data?.error;if(after){renderBrowser(after,{searching:after.state?.editions_status==='refreshing'});const added=Math.max(0,after.editions.length-before.editions.length);if(added)toast(`Edition catalogue updated: ${added} added.`);else if(invokeError)throw invokeError;return;}if(invokeError)throw invokeError;}catch(err){const bundle=await fetchBundle(bookId).catch(()=>null);if(bundle)renderBrowser(bundle,{searching:bundle.state?.editions_status==='refreshing'});toast(err.message||'Could not refresh editions',true);}}

function progressChoice(bundle,e,markOwned){const {book}=bundle,oldTotal=Number(book.total_pages||0),newTotal=Number(e.page_count||0),page=Number(book.current_page||0);if(!oldTotal||!newTotal||oldTotal===newTotal)return applyEdition(bundle,e,markOwned,'page');const percent=Math.round(page/oldTotal*100),converted=Math.min(newTotal,Math.max(0,Math.round(page/oldTotal*newTotal)));modalRoot.innerHTML=`<div class="modal-backdrop edition-progress-backdrop"><div class="modal edition-progress-modal"><h2>Switch reading edition?</h2><p>You are on page <strong>${page}</strong> of ${oldTotal} (${percent}%). The selected edition has ${newTotal} pages.</p><div class="edition-progress-options"><button class="btn btn-primary" type="button" data-progress-mode="percentage">Keep my place · page ${converted}</button><button class="btn" type="button" data-progress-mode="page">Keep page ${Math.min(page,newTotal)}</button><button class="btn" type="button" data-progress-cancel>Cancel</button></div></div></div>`;modalRoot.querySelectorAll('[data-progress-mode]').forEach(b=>b.addEventListener('click',()=>applyEdition(bundle,e,markOwned,b.dataset.progressMode)));modalRoot.querySelector('[data-progress-cancel]')?.addEventListener('click',()=>renderBrowser(bundle));}
async function chooseEdition(bundle,editionId,markOwned){const e=bundle.editions.find(x=>x.id===editionId);if(!e)return;return ['Currently Reading','Paused'].includes(bundle.book.overall_status)?progressChoice(bundle,e,markOwned):applyEdition(bundle,e,markOwned,'page');}
async function applyEdition(bundle,e,markOwned,mode){const button=modalRoot.querySelector(`[data-edition-${markOwned?'own':'use'}="${CSS.escape(e.id)}"]`);if(button){button.disabled=true;button.textContent='Saving…';}try{const {error}=await supabase.rpc('select_book_edition',{p_book_id:bundle.book.id,p_edition_id:e.id,p_mark_owned:markOwned,p_progress_mode:mode,p_source:'frontend'});if(error)throw error;close();toast(markOwned?'Owned edition saved.':'Edition changed.');window.dispatchEvent(new CustomEvent('reading-room:refresh'));}catch(err){toast(err.message||'Could not change edition',true);if(button){button.disabled=false;button.textContent=markOwned?'Use as my edition':'Use this edition';}}}

export async function openEditionBrowser(bookId){try{activeFilter='All';const bundle=await fetchBundle(bookId);const searching=bundle.state?.editions_status==='refreshing';renderBrowser(bundle,{searching});if(searching){followBackground(bookId);return;}const last=bundle.state.editions_last_refreshed_at?new Date(bundle.state.editions_last_refreshed_at).getTime():0,stale=!last||Date.now()-last>30*24*60*60*1000;if(bundle.editions.length<2&&stale)queueMicrotask(()=>discover(bookId,false));}catch(err){toast(err.message||'Could not load editions',true);}}
